    function(el, x) {
      function setNaturalSize() {
        const svg = el.querySelector('svg');

        if (!svg) {
          return false;
        }

        const viewBox = svg.viewBox.baseVal;

        if (
          !viewBox ||
          !Number.isFinite(viewBox.width) ||
          !Number.isFinite(viewBox.height) ||
          viewBox.width <= 0 ||
          viewBox.height <= 0
        ) {
          return false;
        }

        const pointToPixel = 96 / 72;

        const widthPixels = Math.ceil(
          viewBox.width * pointToPixel
        );

        const heightPixels = Math.ceil(
          viewBox.height * pointToPixel
        );

        svg.setAttribute('width', widthPixels);
        svg.setAttribute('height', heightPixels);

        svg.style.setProperty(
          'width',
          widthPixels + 'px',
          'important'
        );

        svg.style.setProperty(
          'height',
          heightPixels + 'px',
          'important'
        );

        svg.style.setProperty(
          'max-width',
          'none',
          'important'
        );

        svg.style.setProperty(
          'display',
          'block',
          'important'
        );

        el.style.setProperty(
          'width',
          widthPixels + 'px',
          'important'
        );

        el.style.setProperty(
          'height',
          heightPixels + 'px',
          'important'
        );

        el.style.setProperty(
          'max-width',
          'none',
          'important'
        );

        el.style.setProperty(
          'overflow',
          'visible',
          'important'
        );

        return true;
      }

      let attempts = 0;

      const interval = window.setInterval(
        function() {
          attempts += 1;

          if (setNaturalSize() || attempts >= 50) {
            window.clearInterval(interval);
          }
        },
        20
      );
    }
    ","data":null}]}}
